export type AgeGroup = '2-4' | '5-7' | '8+' | 'all';

export interface SceneTemplate {
  id: string;
  title: string;
  promptDesc: string;
  ageGroup?: AgeGroup;
}

export interface ThemeConfig {
  slug: string;
  name: string;
  category: string;
  description: string;
  coverPrompts: string[];
  scenes: SceneTemplate[];
}
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

export function formatThemeName(slug: string): string {
  return slug
    .split('-')
    .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
}

