function generateGenericScenes(themeName: string, category: string): SceneTemplate[] {
  return [
    { id: 'sc-1', title: `${themeName} Adventure Begins`, promptDesc: `Embarking enthusiastically into the world of ${themeName}, smiling with great excitement and gear suited for ${category}.` },
    { id: 'sc-2', title: `Exploring ${themeName}`, promptDesc: `Observing the surroundings and uncovering wonderful sights specific to ${themeName}.` },
    { id: 'sc-3', title: `Working Together in ${themeName}`, promptDesc: `Cooperating happily with friendly companions in a vivid ${themeName} environment.` },
    { id: 'sc-4', title: `A Great Discovery`, promptDesc: `Finding an exciting milestone or treasure authentic to ${themeName}.` },
    { id: 'sc-5', title: `Grand Celebration Finale`, promptDesc: `Celebrating victory, happiness, and accomplishment in the world of ${themeName}.` }
  ];
}

