export function getThemeConfig(slug: string, _gender: string = 'all'): ThemeConfig {
  const normalized = slug.toLowerCase().trim();

  // SPECIAL: Surprise Variety Pack (Pulls randomly across all 34 themes)
  if (normalized === 'variety-pack') {
    const allAvailableScenes: SceneTemplate[] = [];
    const excludedSlugs = ['princess', 'ballet-and-dance', 'mermaid-cove'];

    Object.entries(themesData).forEach(([themeSlug, themeConfig]) => {
      if (excludedSlugs.includes(themeSlug)) {
        return;
      }

      if (themeConfig.scenes && themeConfig.scenes.length > 0) {
        // Tag each scene's title with its origin theme for extra excitement
        const taggedScenes = themeConfig.scenes.map((s) => ({
          ...s,
          title: `${themeConfig.name}: ${s.title}`
        }));
        allAvailableScenes.push(...taggedScenes);
      }
    });

    // Fisher-Yates random shuffle
    const shuffled = [...allAvailableScenes];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }

    // Return the top 60 randomized multi-theme scenes
    const selectedScenes = shuffled.slice(0, 60);

    return {
      slug: 'variety-pack',
      name: 'Surprise Variety Pack',
      category: 'Adventure Mix',
      description: 'An ultimate multi-world coloring adventure featuring a curated mix across superheroes, dinosaurs, outer space, sports, and magical worlds!',
      coverPrompts: [
        '2D storybook cover art, vibrant full-color collage illustration showing spaceships, superheroes, friendly dinosaurs, and magical castles together, happy child hero in the center, bold colorful celebration'
      ],
      scenes: selectedScenes.length > 0 ? selectedScenes : generateGenericScenes('Surprise Variety Pack', 'Adventure')
    };
  }

// Standard theme lookup
  if (themesData[normalized]) {
    return themesData[normalized];
  }

  const titleName = formatThemeName(normalized);
  return {
    slug: normalized,
    name: titleName,
    category: 'Jobs',
    description: `Exciting coloring adventures centered around ${titleName}!`,
    coverPrompts: [
      `2D storybook cover art, vibrant full-color illustration of ${titleName}, happy child hero in central focus`
    ],
    scenes: generateGenericScenes(titleName, 'Jobs')
  };
}

// Helper: Select a random cover prompt and substitute placeholders
export function getRandomCoverPrompt(theme: ThemeConfig, childName: string = 'HERO', age: string = '6'): string {
  const covers = (theme.coverPrompts && theme.coverPrompts.length > 0)
    ? theme.coverPrompts
    : [
        `2D children's storybook cover art, vibrant full color, vertical portrait orientation. Large bold 3D typography at the top reading: '{NAME}'S ${theme.name.toUpperCase()} ADVENTURE'. A cheerful {AGE}-year-old child smiling happily in a fun hero pose, colorful themed background, professional children's book cover layout.`
      ];

  const randomIndex = Math.floor(Math.random() * covers.length);
  const selectedTemplate = covers[randomIndex];

  return selectedTemplate
    .replaceAll('{NAME}', (childName || 'HERO').trim().toUpperCase())
    .replaceAll('{AGE}', String(age || '6'));
}

// Helper: Filter scenes by child's age group and return the requested count
export function getScenesForAge(theme: ThemeConfig, ageGroup?: string, count: number = 25): SceneTemplate[] {
  let filtered = theme.scenes;

  if (ageGroup && ageGroup !== 'all') {
    const ageSpecific = theme.scenes.filter(s => !s.ageGroup || s.ageGroup === 'all' || s.ageGroup === ageGroup);
    if (ageSpecific.length > 0) {
      filtered = ageSpecific;
    }
  }

  // Shuffle scenes so every book order gets a fresh, varied selection
  const shuffled = [...filtered];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  return shuffled.slice(0, count);
}

